cd /home/kara/off-by-one && python3 - <<'EOF'
import re
ci=open('.github/workflows/ci.yml').read().splitlines()
# job ids: 2-space indent keys under jobs:
jobs=[]
injobs=False
for i,l in enumerate(ci,1):
    if l.startswith('jobs:'): injobs=True; continue
    if injobs and re.match(r'^  [A-Za-z0-9_-]+:\s*$', l):
        jobs.append((i,l.strip().rstrip(':')))
print("CI JOB IDS (%d):"%len(jobs))
for i,j in jobs: print("  line %d: %s"%(i,j))
# job display names
names=[]
for i,l in enumerate(ci,1):
    m=re.match(r'^    name: (.+)$', l)
    if m: names.append((i,m.group(1)))
print("CI JOB DISPLAY NAMES (%d):"%len(names))
for i,n in names: print("  line %d: %s"%(i,n))
rd=open('README.md').read().splitlines()
print("README CI/CD bullets:")
for i,l in enumerate(rd,1):
    if 595<=i<=610 and l.startswith('- **'):
        print("  line %d: %s"%(i,l[:110]))
EOF
